Question: Implement a thread-safe solution to the Producer-Consumer Bounded Buffer Problem using POSIX counting semaphores (empty, full) and a mutex lock in C/C++ pseudo-code.
Maximum Marks: 15.0

Reference Model Answer / Rubric:
Thread-safe bounded buffer requires: sem_t empty (initialized to BUFFER_SIZE), sem_t full (initialized to 0), and pthread_mutex_t mutex. Producer code: sem_wait(&empty); pthread_mutex_lock(&mutex); buffer[in] = item; in = (in + 1) % BUFFER_SIZE; pthread_mutex_unlock(&mutex); sem_post(&full); Consumer code: sem_wait(&full); pthread_mutex_lock(&mutex); item = buffer[out]; out = (out + 1) % BUFFER_SIZE; pthread_mutex_unlock(&mutex); sem_post(&empty); Order of sem_wait before mutex_lock is critical to prevent deadlock.

Student's Answer:
#define N 10
sem_t empty, full;
pthread_mutex_t mtx;

void init() {
    sem_init(&empty, 0, N);
    sem_init(&full, 0, 0);
    pthread_mutex_init(&mtx, NULL);
}

void* producer(void* arg) {
    while(1) {
        int item = produce();
        sem_wait(&empty);
        pthread_mutex_lock(&mtx);
        buffer[in] = item;
        in = (in + 1) % N;
        pthread_mutex_unlock(&mtx);
        sem_post(&full);
    }
}

void* consumer(void* arg) {
    while(1) {
        sem_wait(&full);
        pthread_mutex_lock(&mtx);
        int item = buffer[out];
        out = (out + 1) % N;
        pthread_mutex_unlock(&mtx);
        sem_post(&empty);
        consume(item);
    }
}

